INSERT INTO TBL_BIZI_MST (BIZ_CD, JOB_SEQ, ACTION_YN, BIZ_NM, REG_DTTM, REG_USER, REG_IP)
SELECT #{bizCd}, 1, 'Y', #{bizNm}, GETDATE(), #{regUser}, #{regIp}
 WHERE NOT EXISTS (SELECT 1 FROM TBL_BIZI_MST t WHERE t.BIZ_CD = #{bizCd})

mapper.update:
UPDATE TBL_BIZI_MST
   SET BIZ_NM = #{bizNm}, ACTION_YN = 'Y',
       UPD_DTTM = GETDATE(), UPD_USER = #{updUser}, UPD_IP = #{updIp}
 WHERE BIZ_CD = #{bizCd}

UPDATE TBL_BIZI_MST
   SET ACTION_YN = 'N',
       UPD_DTTM = GETDATE(), UPD_USER = #{updUser}, UPD_IP = #{updIp}
 WHERE BIZ_CD = #{bizCd}

UPDATE TBL_RECEIVE_MST
   SET BIZ_NM=#{bizNm,jdbcType=NVARCHAR}, PREV_AMT=#{prevAmt,jdbcType=DECIMAL}, SALES_AMT=#{salesAmt,jdbcType=DECIMAL}, COLLECT_AMT=#{collectAmt,jdbcType=DECIMAL},
       COLLECT_DT=REPLACE(ISNULL(#{collectDt,jdbcType=NVARCHAR},''),'-',''), PAY_GB=#{payGb,jdbcType=NVARCHAR}, REMARK=#{remark,jdbcType=NVARCHAR},
       UPD_DTTM=CONVERT(VARCHAR(19),GETDATE(),120), UPD_USER=#{updUser,jdbcType=NVARCHAR}, UPD_IP=#{updIp,jdbcType=NVARCHAR}
 WHERE RCV_SEQ = #{rcvSeq}

UPDATE TBL_PAYMENT_MST
   SET BIZ_NM=#{bizNm,jdbcType=NVARCHAR}, PREV_AMT=#{prevAmt,jdbcType=DECIMAL}, PURCH_AMT=#{purchAmt,jdbcType=DECIMAL}, PAYOUT_AMT=#{payoutAmt,jdbcType=DECIMAL},
       PAYOUT_DT=REPLACE(ISNULL(#{payoutDt,jdbcType=NVARCHAR},''),'-',''), PAY_GB=#{payGb,jdbcType=NVARCHAR}, REMARK=#{remark,jdbcType=NVARCHAR},
       UPD_DTTM=CONVERT(VARCHAR(19),GETDATE(),120), UPD_USER=#{updUser,jdbcType=NVARCHAR}, UPD_IP=#{updIp,jdbcType=NVARCHAR}
 WHERE PAY_SEQ = #{paySeq}

UPDATE TBL_SETTLE_CLOSE_MST
   SET STATUS='N', UPD_DTTM=CONVERT(VARCHAR(19),GETDATE(),120), UPD_USER=#{updUser,jdbcType=NVARCHAR}
 WHERE SETTLE_GB = #{settleGb} AND CLOSE_YM = REPLACE(#{closeYm},'-','')

UPDATE TBL_PROD_MST
   SET ACTION_YN='N', UPD_DTTM=CONVERT(VARCHAR(19), GETDATE(), 120), UPD_USER=#{updUser,jdbcType=NVARCHAR}, UPD_IP=#{updIp,jdbcType=NVARCHAR}
 WHERE PROD_SEQ = #{prodSeq}

UPDATE TBL_PROD_INPRICE_HST
   SET ACTION_YN='N', UPD_DTTM=CONVERT(VARCHAR(19), GETDATE(), 120), UPD_USER=#{updUser,jdbcType=NVARCHAR}, UPD_IP=#{updIp,jdbcType=NVARCHAR}
 WHERE INPRICE_SEQ = #{inpriceSeq}

UPDATE TBL_PROD_MST
   SET IN_PRICE = #{inPrice,jdbcType=DECIMAL},
       UPD_DTTM = CONVERT(VARCHAR(19), GETDATE(), 120), UPD_USER=#{regUser,jdbcType=NVARCHAR}, UPD_IP=#{regIp,jdbcType=NVARCHAR}
 WHERE PROD_SEQ = #{prodSeq}

UPDATE TBL_PROD_SALEPRICE_HST
   SET ACTION_YN='N', UPD_DTTM=CONVERT(VARCHAR(19), GETDATE(), 120), UPD_USER=#{updUser,jdbcType=NVARCHAR}, UPD_IP=#{updIp,jdbcType=NVARCHAR}
 WHERE SALEPRICE_SEQ = #{salepriceSeq}

UPDATE TBL_PROD_MST
   SET SALE_PRICE  = #{salePrice,jdbcType=DECIMAL},
       WHOLE_PRICE = ISNULL(#{wholePrice,jdbcType=DECIMAL}, WHOLE_PRICE),
       UPD_DTTM = CONVERT(VARCHAR(19), GETDATE(), 120), UPD_USER=#{regUser,jdbcType=NVARCHAR}, UPD_IP=#{regIp,jdbcType=NVARCHAR}
 WHERE PROD_SEQ = #{prodSeq}

UPDATE TBL_STOCK_LEDGER
   SET ACTION_YN='N', UPD_DTTM=CONVERT(VARCHAR(19), GETDATE(), 120), UPD_USER=#{updUser,jdbcType=NVARCHAR}, UPD_IP=#{updIp,jdbcType=NVARCHAR}
 WHERE LEDGER_SEQ = #{ledgerSeq}
